#!/usr/bin/env node
/**
 * Test: every secret path family of the shell guard (hooks/lib/secret-read.js: SECRET_BASENAME, SECRET_PATH)
 * has a matching `Read(...)` deny in settings.json, so the Read tool is no wider a door than the shell.
 *
 * Generated by Claude Code at the user's request.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const settings = JSON.parse(readFileSync(join(dirname(fileURLToPath(import.meta.url)), '..', 'settings.json'), 'utf8'));
const deny = new Set(settings.permissions.deny);

// One rule per family listed in hooks/lib/secret-read.js (SECRET_BASENAME + SECRET_PATH).
const FAMILIES = {
  '.env': 'Read(//**/.env)',
  '.env.test': 'Read(//**/.env.test)',
  '.env.prod': 'Read(//**/.env.prod)',
  '*.pem': 'Read(//**/*.pem)',
  '*.key': 'Read(//**/*.key)',
  '*.pfx': 'Read(//**/*.pfx)',
  '*.p12': 'Read(//**/*.p12)',
  '*.jks': 'Read(//**/*.jks)',
  id_rsa: 'Read(//**/id_rsa*)',
  id_ed25519: 'Read(//**/id_ed25519*)',
  id_ecdsa: 'Read(//**/id_ecdsa*)',
  id_dsa: 'Read(//**/id_dsa*)',
  '~/.ssh': 'Read(~/.ssh/**)',
  msal_token_cache: 'Read(~/.azure*/msal_token_cache*)',
  service_principal_entries: 'Read(~/.azure*/service_principal_entries*)',
  '.claude.json': 'Read(~/.claude.json)',
  '.credentials.json': 'Read(~/.claude/.credentials.json)',
  '.git-credentials': 'Read(~/.git-credentials)',
  '.npmrc': 'Read(//**/.npmrc)',
  '.pgpass': 'Read(//**/.pgpass)',
  '.netrc': 'Read(//**/.netrc)',
  '_netrc': 'Read(//**/_netrc)',
  kubeconfig: 'Read(//**/kubeconfig)',
  'secrets.json': 'Read(//**/secrets.json)',
  'gh/hosts.yml': 'Read(~/.config/gh/hosts.yml)',
  '.docker/config.json': 'Read(~/.docker/config.json)',
  '.aws/credentials': 'Read(~/.aws/credentials)',
  '.kube/config': 'Read(~/.kube/config)',
};

for (const [family, rule] of Object.entries(FAMILIES)) {
  test(`given the secret family ${family} of the shell guard, when settings.json deny is read, then ${rule} is denied`, () => {
    // Given / When
    const denied = deny.has(rule);

    // Then
    assert.equal(denied, true, `${rule} missing from permissions.deny`);
  });
}
